import { createFileRoute } from "@tanstack/react-router";
import { FolderKanban } from "lucide-react";

import { ProjectsTable, useProjects } from "@/features/projects";
import { ContentPage } from "@/features/shell";

export const Route = createFileRoute("/_authenticated/projects")({
  staticData: { title: "Projetos" },
  head: () => ({
    meta: [
      { title: "Projetos — Arquiteto de Infraestrutura IA" },
      { name: "robots", content: "noindex" },
    ],
  }),
  component: ProjectsPage,
});

/** Projects generated by the portal, with publication and Git status. */
function ProjectsPage() {
  const { projects, loading } = useProjects();

  return (
    <ContentPage
      icon={FolderKanban}
      title="Projetos"
      description="Projetos de infraestrutura gerados pelo portal, com o status de publicação e a sincronização com o repositório Git."
      size="wide"
    >
      <ProjectsTable projects={projects} loading={loading} />
    </ContentPage>
  );
}
